const items = $input.all();

return items.map(item => {
  const data = item.json;

  const prompt = `
Rispondi solo con JSON valido, senza markdown e senza spiegazioni.
Sei un AI Social Content Strategist per artisti musicali e creator.
Analizza questo contenuto social e genera output utili per una campagna professionale.

Dati contenuto:
Titolo contenuto: ${data["Titolo contenuto"]}
Canale: ${data["Canale"]}
Target: ${data["Target"]}
Obiettivo: ${data["Obiettivo"]}
Mood: ${data["Mood"]}
Tema: ${data["Tema"]}
Formato: ${data["Formato"]}

Esempio di stile desiderato:
Hook: "La notte in cui cambia tutto"
Caption: "Un contenuto pensato per trasformare l’attesa in identità: visual forte, tono premium e messaggio diretto per presentare il brano come un momento, non solo come un’uscita."
CTA: "Ascoltalo appena esce."

Restituisci esattamente questo JSON:
{
  "hook": "",
  "caption": "",
  "cta": "",
  "idea_visual": "",
  "prompt_immagine": "",
  "priorita_contenuto": "",
  "motivazione_priorita": ""
}

Regole:
- Scrivi in italiano naturale, credibile e professionale
- Non usare emoji
- Non usare hashtag
- Non usare punti esclamativi eccessivi
- Hook massimo 10 parole
- Caption massimo 350 caratteri
- CTA massimo 12 parole
- Tono: urban, premium, diretto, credibile
- Evita frasi cringe, motivazionali generiche o troppo aggressive
- Evita parole come: bomba, spacca, non perderti, incredibile, successo assicurato
- idea_visual deve essere concreta e realizzabile per uno shooting o post social
- prompt_immagine deve essere in inglese, fotografico/cinematografico, senza testo scritto nell'immagine
- priorita_contenuto può essere solo Alta, Media o Bassa
- motivazione_priorita massimo 1 frase
`;

  return {
    json: {
      ...data,
      ollamaBody: {
        model: "mistral:7b",
        prompt,
        stream: false,
        format: "json"
      }
    }
  };
});

const rawResponse = $input.first().json.response;

if (!rawResponse) {
  throw new Error("Non trovo il campo response. Controlla che questo nodo sia collegato dopo HTTP Request.");
}

let parsed;

try {
  parsed = JSON.parse(rawResponse);
} catch (error) {
  throw new Error("La risposta di Ollama non è JSON valido: " + rawResponse);
}

return [
  {
    json: {
      Hook: parsed.hook || "",
      Caption: parsed.caption || "",
      CTA: parsed.cta || "",
      "Idea visual": parsed.idea_visual || "",
      "Prompt immagine": parsed.prompt_immagine || "",
      "Priorità contenuto": parsed.priorita_contenuto || "",
      "Motivazione priorità": parsed.motivazione_priorita || "",
      Stato: "Da revisionare"
    }
  }
];

const generatedItems = $input.all();

let message = '✅ PIANO EDITORIALE GENERATO\n\n';

generatedItems.forEach((item, index) => {
  const data = item.json;

  message += `CONTENUTO ${index + 1}\n`;
  message += `Hook: ${data.Hook || ''}\n\n`;
  message += `Caption: ${data.Caption || ''}\n\n`;
  message += `CTA: ${data.CTA || ''}\n\n`;
  message += `Idea visual: ${data["Idea visual"] || ''}\n\n`;
  message += `Prompt immagine: ${data["Prompt immagine"] || ''}\n\n`;
  message += `Priorità: ${data["Priorità contenuto"] || ''}\n`;
  message += `Motivazione: ${data["Motivazione priorità"] || ''}\n`;
  message += `Stato: ${data.Stato || 'Da revisionare'}\n`;
  message += `\n-------------------------\n\n`;
});

return [
  {
    json: {
      messaggio_finale: message
    }
  }
];

const message = $input.first().json.messaggio_finale || '';

const html = `
<!DOCTYPE html>
<html lang="it">
<head>
  <meta charset="UTF-8">
  <title>Piano Editoriale AI</title>
</head>
<body style="
  margin: 0;
  padding: 0;
  background: #ffffff;
  color: #111111;
  font-family: Arial, sans-serif;
">

  <div style="
    max-width: 900px;
    margin: 0 auto;
    padding: 40px;
    background: #ffffff;
    color: #111111;
    line-height: 1.6;
  ">

    <h1 style="
      color: #111111;
      border-bottom: 2px solid #111111;
      padding-bottom: 12px;
    ">
      Piano Editoriale AI
    </h1>

    <pre style="
      white-space: pre-wrap;
      word-wrap: break-word;
      background: #f5f5f5;
      color: #111111;
      padding: 24px;
      border-radius: 8px;
      border: 1px solid #dddddd;
      font-size: 15px;
      line-height: 1.6;
      font-family: Arial, sans-serif;
    ">${message}</pre>

  </div>

</body>
</html>
`;

return [
  {
    json: {
      html_finale: html
    }
  }
];
